   group('SettingsRepository', () {
     late SettingsRepository settingsRepository;

     setUp(() {
       settingsRepository = SettingsRepositoryImpl(mockPreferenceDatasource);
     });

     test('should complete initialization without errors', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('my-token'));

       await settingsRepository.initAsyncData();

       verify(settingsRepository.initAsyncData()).called(1);
     });

     test('readThemeMode returns the datasource current theme mode value', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value(null));
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);

       await settingsRepository.initAsyncData();

       final result = settingsRepository.readThemeMode();

       expect(result, AppThemeMode.dark);
     });

     test('readThemeMode returns different modes as set in datasource', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value(null));
       settingsRepository.setThemeMode(AppThemeMode.light);

       final resultLight = settingsRepository.readThemeMode();
       expect(resultLight, AppThemeMode.light);

       settingsRepository.setThemeMode(AppThemeMode.system);

       final resultSystem = settingsRepository.readThemeMode();
       expect(resultSystem, AppThemeMode.system);
     });

     test('readThemeMode is safely callable after initAsyncData', () async {
       when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value(null));
       when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);

       await settingsRepository.initAsyncData();

       final result = settingsRepository.readThemeMode();

       expect(result, AppThemeMode.dark);
       verify(settingsRepository.initAsyncData()).called(1);
     });
   });", "path":"}

