      final stream = Stream<String?>.fromIterable(['token', null]);

      expectLater(
        settingsRepository.isAuthStream,
        emitsInOrder([true, false]),
      );

      await for (final token in stream) {
        settingsRepository.setToken(token);
      }
    });
  });
