    });

    test('should return correct currency list when getCurrencyList is called', () async {
      final currencyList = [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Доллар США',
          symbol: 'USD',
          value: 78.4181,
          previousValue: 78.5,
        ),
        CurrencyModel(
          id: '2',
