      expect(result, currencyList);
      verify(mockRestDatasource.getCurrencyList()).called(1);
    });

    test('fetchRates returns requested page and hasMore flag', () async {
      final all = [
        for (int i = 0; i < 3; i++)
          CurrencyModel(id: '$i', nominal: 1, name: 'Валюта $i', symbol: 'C$i', value: i + 1.0, previousValue: i.toDouble()),
      ];
      when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => all);

      final page0 = await repository.fetchRates(const CurrencyPageRequest(page: 0, pageSize: 2));

      expect(page0.items.map((c) => c.id), ['0', '1']);
      expect(page0.hasMore, isTrue);
    });

    test('fetchRates returns empty page beyond the end', () async {
      when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => const []);

      final page = await repository.fetchRates(const CurrencyPageRequest(page: 5, pageSize: 20));

      expect(page.items, isEmpty);
      expect(page.hasMore, isFalse);
    });

    test('should complete successfully when saveCurrencyList is called', () async {
      final currencyList = [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Юань',
          symbol: 'CNY',
          value: 10.9384,
          previousValue: 10.9112,
        ),
      ];

      await repository.saveCurrencyList(currencyList);

      verify(mockDbDatasource.saveCurrencyList(currencyList)).called(1);
    });
  });

  group('NewsRepository', () {
    late NewsRepository repository;

    setUp(() {
      reset(mockRestDatasource);
      reset(mockDbDatasource);
      repository = NewsRepositoryImpl(mockRestDatasource, mockDbDatasource);
    });

    test('should return news list when getNewsList is called', () async {
      final newsList = [
        for (int i = 0; i < 3; i++)
          NewsModel(title: 'Заголовок $i', link: 'https://example.com/$i', date: DateTime.now()),
      ];

      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final result = await repository.getNewsList();

      expect(result, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
    });

    test('loadNewsFeed with forceRefresh reads from network and caches', () async {
      final newsList = [
        NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime.now()),
      ];
      when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);

      final result = await repository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));

      expect(result, newsList);
      verify(mockRestDatasource.getNewsList()).called(1);
      verify(mockDbDatasource.saveNewsList(newsList)).called(1);
      verifyNever(mockDbDatasource.getNewsList());
    });

    test('loadNewsFeed without forceRefresh reads only from cache', () async {
      final cached = [
        NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
      ];
      when(mockDbDatasource.getNewsList()).thenAnswer((_) async => cached);

      final result = await repository.loadNewsFeed(NewsFeedFilter.all);

      expect(result, cached);
      verify(mockDbDatasource.getNewsList()).called(1);
      verifyNever(mockRestDatasource.getNewsList());
    });

    test('should complete successfully when saveNewsList is called', () async {
      final newsList = [
        NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      ];

      await repository.saveNewsList(newsList);

      verify(mockDbDatasource.saveNewsList(newsList)).called(1);
    });
  });

  group('SettingsRepository', () {
    late SettingsRepository settingsRepository;

    setUp(() {
      reset(mockPreferenceDatasource);
      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value(null));
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);
      settingsRepository = SettingsRepositoryImpl(mockPreferenceDatasource);
    });

    test('should complete initialization without errors', () async {
      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('my-token'));

      await settingsRepository.initAsyncData();

      verify(settingsRepository.initAsyncData()).called(1);
    });

    test('readThemeMode returns the datasource current theme mode value', () async {
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);

      final result = settingsRepository.readThemeMode();

      expect(result, AppThemeMode.dark);
    });

    test('readThemeMode returns different modes as set in datasource', () async {
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);
      var resultLight = settingsRepository.readThemeMode();
      expect(resultLight, AppThemeMode.light);

      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.system);
      var resultSystem = settingsRepository.readThemeMode();
      expect(resultSystem, AppThemeMode.system);

      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);
      var resultDark = settingsRepository.readThemeMode();
      expect(resultDark, AppThemeMode.dark);
    });

    test('readThemeMode is safely callable after initAsyncData', () async {
      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value(null));
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.dark);

      await settingsRepository.initAsyncData();

      final result = settingsRepository.readThemeMode();

      expect(result, AppThemeMode.dark);
    });

    test('should return correct token when getToken is called', () async {
      when(mockPreferenceDatasource.getToken()).thenAnswer((_) => Future.value('my-token'));

      final token = await settingsRepository.getToken();

      expect(token, 'my-token');
      verify(settingsRepository.getToken()).called(1);
    });

    test('should complete token setting successfully', () async {
      when(mockPreferenceDatasource.setToken(any)).thenReturn(null);
      await settingsRepository.setToken('abc');

      verify(mockPreferenceDatasource.setToken('abc')).called(1);
    });

    test('should set theme mode with correct value', () {
      when(mockPreferenceDatasource.setThemeMode(any)).thenReturn(null);
      settingsRepository.setThemeMode(AppThemeMode.dark);

      verify(mockPreferenceDatasource.setThemeMode(AppThemeMode.dark)).called(1);
    });

    test('should return current theme mode value', () {
      when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.light);

      final result = settingsRepository.themeMode;

      expect(result, AppThemeMode.light);
    });

    test('should emit theme mode changes through stream', () async {
      final stream = Stream<AppThemeMode>.fromIterable([
        AppThemeMode.system,
        AppThemeMode.dark,
      ]);

      expectLater(
        settingsRepository.themeModeStream,
        emitsInOrder([AppThemeMode.system, AppThemeMode.dark]),
      );

      await for (final mode in stream) {
        when(mockPreferenceDatasource.setThemeMode(any)).thenReturn(null);
        settingsRepository.setThemeMode(mode);
      }
    });

    test('should emit auth state changes through stream', () async {
      final stream = Stream<String?>.fromIterable(['token', null]);

      expectLater(
        settingsRepository.isAuthStream,
        emitsInOrder([true, false]),
      );

      await for (final token in stream) {
        when(mockPreferenceDatasource.setToken(any)).thenReturn(null);
        settingsRepository.setToken(token);
      }
    });
  });
}
